-- purpose:  Open complaints with hours left on their SLA (negative = breached) and when the next escalation level falls due. This is the work list of sp_escalate_overdue().
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT complaint_id, title, status, ward_name, hours_left,
       current_level, next_level, next_level_due_at
FROM vw_sla_breach_candidates
ORDER BY hours_left
LIMIT 15;
